BEGIN;
CREATE FUNCTION pg_temp.ins_assert(ok boolean) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS NOT TRUE THEN RAISE EXCEPTION 'FALLA checklist'; END IF; END $$;
INSERT INTO auth.users(id) VALUES('00000000-0000-0000-0000-00000000ac01'),('00000000-0000-0000-0000-00000000ac02');
INSERT INTO public.team_members(id,name,email,role,active) VALUES('00000000-0000-0000-0000-00000000ac01','Limpieza Sintética','ins-clean@example.test','cleaning',true),('00000000-0000-0000-0000-00000000ac02','Inactivo Sintético','ins-inactive@example.test','cleaning',false);
INSERT INTO public.properties(id,name,capacity) VALUES('00000000-0000-0000-0000-00000000ac11','Checklist Sintético',4);
INSERT INTO public.reservations(id,property_id,source,guest_name,check_in,check_out,status) VALUES('00000000-0000-0000-0000-00000000ac21','00000000-0000-0000-0000-00000000ac11','direct','Huésped Sintético',(clock_timestamp() AT TIME ZONE 'America/Bogota')::date,(clock_timestamp() AT TIME ZONE 'America/Bogota')::date+2,'confirmed');
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claim.sub='00000000-0000-0000-0000-00000000ac01';
CREATE FUNCTION pg_temp.ins_record(item text,result text,note text,v int,k text,photo text DEFAULT NULL) RETURNS jsonb LANGUAGE sql AS $$ SELECT public.record_arrival_inspection('00000000-0000-0000-0000-00000000ac21','00000000-0000-0000-0000-00000000ac11',(clock_timestamp() AT TIME ZONE 'America/Bogota')::date,(clock_timestamp() AT TIME ZONE 'America/Bogota')::date+2,item,result,note,photo,v,k) $$;
SELECT pg_temp.ins_assert((pg_temp.ins_record('air','issue','No enfría el aire sintético',0,'first')->>'ok')::boolean);
SELECT pg_temp.ins_assert((pg_temp.ins_record('air','issue','No enfría el aire sintético',0,'first')->>'replayed')::boolean);
SELECT pg_temp.ins_assert((SELECT count(*)=1 FROM public.maintenance WHERE property_id='00000000-0000-0000-0000-00000000ac11' AND priority='urgent'));
SELECT pg_temp.ins_assert((pg_temp.ins_record('air','issue','Persiste falla sintética',1,'second')->>'ok')::boolean);
SELECT pg_temp.ins_assert((SELECT count(*)=1 FROM public.maintenance WHERE property_id='00000000-0000-0000-0000-00000000ac11'));
SELECT pg_temp.ins_assert((pg_temp.ins_record('lights','checked','',1,'stale')->>'conflict')::boolean);
SELECT pg_temp.ins_assert((pg_temp.ins_record('air','checked','Revisión física sintética',2,'third')->>'ok')::boolean);
SELECT pg_temp.ins_assert((SELECT count(*)=1 FROM public.maintenance WHERE property_id='00000000-0000-0000-0000-00000000ac11' AND status<>'resolved'));
SELECT pg_temp.ins_assert((SELECT checks->'air'->>'actor_id'='00000000-0000-0000-0000-00000000ac01' AND checks->'air'->>'at' IS NOT NULL FROM public.arrival_inspections WHERE reservation_id='00000000-0000-0000-0000-00000000ac21'));
DO $$ BEGIN
 BEGIN PERFORM pg_temp.ins_record('water','issue','Fuga sintética',3,'missing-photo','00000000-0000-0000-0000-00000000ac01/00000000-0000-0000-0000-00000000ac21/00000000-0000-0000-0000-00000000ac31.jpg'); RAISE EXCEPTION 'FALLA foto inexistente'; EXCEPTION WHEN check_violation THEN NULL; END;
 BEGIN UPDATE public.arrival_inspections SET checks='{}'; RAISE EXCEPTION 'FALLA DML'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
END $$;
INSERT INTO storage.objects(bucket_id,name) VALUES('inspection-evidence','00000000-0000-0000-0000-00000000ac01/00000000-0000-0000-0000-00000000ac21/00000000-0000-0000-0000-00000000ac31.jpg');
SELECT pg_temp.ins_assert((pg_temp.ins_record('water','issue','Fuga sintética',3,'with-photo','00000000-0000-0000-0000-00000000ac01/00000000-0000-0000-0000-00000000ac21/00000000-0000-0000-0000-00000000ac31.jpg')->>'ok')::boolean);
SET LOCAL request.jwt.claim.sub='00000000-0000-0000-0000-00000000ac02';
SELECT pg_temp.ins_assert((SELECT count(*)=0 FROM storage.objects WHERE bucket_id='inspection-evidence'));
SELECT pg_temp.ins_assert((SELECT count(*)=0 FROM public.arrival_inspections));
RESET ROLE;
UPDATE public.reservations SET status='cancelled' WHERE id='00000000-0000-0000-0000-00000000ac21';
SELECT pg_temp.ins_assert((SELECT invalidated_at IS NOT NULL AND version=5 FROM public.arrival_inspections WHERE reservation_id='00000000-0000-0000-0000-00000000ac21'));
UPDATE public.reservations SET status='confirmed' WHERE id='00000000-0000-0000-0000-00000000ac21';
SELECT pg_temp.ins_assert((SELECT invalidated_at IS NOT NULL AND version=6 FROM public.arrival_inspections WHERE reservation_id='00000000-0000-0000-0000-00000000ac21'));
SELECT pg_temp.ins_assert((SELECT public=false FROM storage.buckets WHERE id='inspection-evidence'));
ROLLBACK;
